function gerarProtocolo(){let o=Number(localStorage.getItem("ultimoProtocolo"))||0;return o++,localStorage.setItem("ultimoProtocolo",o),`FL-${String(o).padStart(6,"0")}`}function salvarDoacao(o){const t=JSON.parse(localStorage.getItem("doacoes"))||[],r={...o,protocolo:gerarProtocolo()};return t.push(r),localStorage.setItem("doacoes",JSON.stringify(t)),r}function salvarVoluntario(o){const t=JSON.parse(localStorage.getItem("voluntarios"))||[];return t.push(o),localStorage.setItem("voluntarios",JSON.stringify(t)),o}